// Freya Bank voice statement/debt services: mock for the test environment (Cloudflare Worker, ES module).
//
// Follows the bank's service contract of 1 October 2026 (sections 3-6) and serves, byte for byte, the answers
// of test-environment/test-customers.json (RECORDS in records.js, generated by gen_records.py).
//
//   POST /voice/v1/cards.list             data.customerNo                    -> 404 FB_IVR_CHANNEL_102 if unknown
//   POST /voice/v1/cards.balance          data.cardNumber                    -> 404 FB_IVR_CHANNEL_120 if unknown
//   POST /voice/v1/statement.week.get     data.cardNumber                    -> 404 FB_IVR_CHANNEL_121 if unknown
//   POST /voice/v1/statement.week.decide  data.cardNumber + newStatementWeek -> 400 INVALID_ARGUMENTS_ERROR if no entry
//   POST /voice/v1/statement.week.change  data.cardNumber + newStatementWeek -> 400 INVALID_ARGUMENTS_ERROR if no entry
//   POST /voice/v1/contact.email.get      data.customerNo                    -> 400 INVALID_ARGUMENTS_ERROR if unknown
//   POST /voice/v1/statement.pdf.send     data.customerNo                    -> 404 FB_IVR_CHANNEL_107 if no entry
//   POST /oauth2/token                    test token (the test environment does not check tokens)
//   GET  /health                          {"ok": true}
//
// Only the `data` fields decide the answer; token, headers and `call` are not checked (contract section 6).
// Stateless: statement.week.change does not alter later answers, exactly like the test data.

import { CUSTOMERS, CARDS, SAMPLE } from "./records.js";

const BASE = "/voice/v1/";
const ORIGIN = "ivr-gateway-test:ivr-channel-v0";
const NOT_FOUND_CAUSE = "com.freyabank.ivrgateway.ivrchannel.rest.exception.NotFoundException";
const INVALID_CAUSE = "com.freyabank.ivrgateway.ivrchannel.rest.exception.InvalidArgumentsException";

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "*",
};
const JSON_HEADERS = { "Content-Type": "application/json; charset=utf-8", ...CORS };

// ------------------------------------------------------------------------------------------------ responses

function newGuid() {
  return crypto.randomUUID().replace(/-/g, "");
}

function send(text, status, extraHeaders) {
  return new Response(text, { status, headers: { ...JSON_HEADERS, ...(extraHeaders || {}) } });
}

// Contract section 4: error answers have no `data`, only `result`.
function errorBody(code, message, type, rootCause, origin) {
  const guid = newGuid();
  return {
    result: {
      guid,
      returnCode: code,
      messageText: message,
      code,
      message,
      type,
      details: { guid, rootCause, errorOrigin: origin || ORIGIN },
    },
  };
}

function invalid(message) {
  return send(JSON.stringify(errorBody("INVALID_ARGUMENTS_ERROR", message, "ERROR", INVALID_CAUSE)), 400);
}

function notFound(code, message) {
  return send(JSON.stringify(errorBody(code, message, "WARNING", NOT_FOUND_CAUSE)), 404);
}

// Per service: what to answer when the customer/card (or week) has no entry in the test data
// (contract section 6: the service's 404 from section 4, else a 400 INVALID_ARGUMENTS_ERROR).
const NO_ENTRY = {
  "cards.list": () => notFound("FB_IVR_CHANNEL_102", "Müşteriye ait geçerli kart bilgisi bulunamadı."),
  "cards.balance": () => notFound("FB_IVR_CHANNEL_120", "Kart bakiye servisi hatası: kart bulunamadı"),
  "statement.week.get": () => notFound("FB_IVR_CHANNEL_121", "Ekstre haftası servisi hatası: kart bulunamadı"),
  "statement.week.decide": (what) => invalid(what || "card number not found"),
  "statement.week.change": (what) => invalid(what || "card number not found"),
  "contact.email.get": () => invalid("customer number not found"),
  "statement.pdf.send": () => notFound("FB_IVR_CHANNEL_107", "Pdf dokümanı bulunamadı"),
};

async function serve(entry, env) {
  if (entry.delaySeconds) {
    const scale = env && env.DELAY_SCALE !== undefined ? Number(env.DELAY_SCALE) : 1;
    const ms = entry.delaySeconds * 1000 * (Number.isFinite(scale) && scale >= 0 ? scale : 1);
    if (ms > 0) await new Promise((resolve) => setTimeout(resolve, ms));
  }
  return send(entry.body, entry.http);
}

// ------------------------------------------------------------------------------------------------ request fields

// The panel's "Test API Request" button may send variables without filling them in, e.g. "{{customerNumber}}".
function isTemplateVariable(value) {
  if (typeof value !== "string") return false;
  const v = value.trim();
  return v.startsWith("{{") || v.toUpperCase().startsWith("%7B%7B");
}

// customerNo / cardNumber / dates may come as string or number; anything else counts as empty.
function text(value) {
  if (typeof value === "string") return value.trim();
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  return "";
}

// newStatementWeek: 3 or "3" (also " 3", "03").
function week(value) {
  const t = text(value);
  return /^\d+$/.test(t) ? String(parseInt(t, 10)) : t;
}

const LABEL = { customerNo: "customer number", cardNumber: "card number" };

// Contract section 4: a required field missing or empty -> 400, message names the field.
function missing(data, fields) {
  for (const f of fields) {
    if (!text(data[f])) return invalid(`${LABEL[f] || f} cannot be empty`);
  }
  return null;
}

// ------------------------------------------------------------------------------------------------ services

function byCustomer(service, required) {
  return async (data, env) => {
    const bad = missing(data, required);
    if (bad) return bad;
    const customerNo = isTemplateVariable(data.customerNo) ? SAMPLE.customerNo : text(data.customerNo);
    const entry = (CUSTOMERS[customerNo] || {})[service];
    return entry ? serve(entry, env) : NO_ENTRY[service]();
  };
}

function byCard(service) {
  return async (data, env) => {
    const bad = missing(data, ["cardNumber"]);
    if (bad) return bad;
    const cardNumber = isTemplateVariable(data.cardNumber) ? SAMPLE.cardNumber : text(data.cardNumber);
    const entry = (CARDS[cardNumber] || {})[service];
    return entry ? serve(entry, env) : NO_ENTRY[service]();
  };
}

function byCardAndWeek(service) {
  return async (data, env) => {
    const bad = missing(data, ["cardNumber", "newStatementWeek", "statementDay"]);
    if (bad) return bad;
    const sampleCard = isTemplateVariable(data.cardNumber);
    const cardNumber = sampleCard ? SAMPLE.cardNumber : text(data.cardNumber);
    const weeks = (CARDS[cardNumber] || {})[service];
    if (!weeks) return NO_ENTRY[service]("card number not found");
    let entry = weeks[week(data.newStatementWeek)];
    if (!entry && (sampleCard || isTemplateVariable(data.newStatementWeek))) entry = weeks[Object.keys(weeks)[0]];
    // No entry for that week (e.g. the card's current week, or not 1-4): nothing to preview/change.
    return entry ? serve(entry, env) : NO_ENTRY[service]("newStatementWeek is not valid for this card");
  };
}

const SERVICES = {
  "cards.list": byCustomer("cards.list", ["customerNo"]),
  "cards.balance": byCard("cards.balance"),
  "statement.week.get": byCard("statement.week.get"),
  "statement.week.decide": byCardAndWeek("statement.week.decide"),
  "statement.week.change": byCardAndWeek("statement.week.change"),
  "contact.email.get": byCustomer("contact.email.get", ["customerNo", "intAddressInfoType"]),
  "statement.pdf.send": byCustomer("statement.pdf.send",
    ["customerNo", "cardNumber", "currencyType", "statementDate", "emailAddress"]),
};

const ROUTES = ["GET /health", "POST /oauth2/token"].concat(Object.keys(SERVICES).map((s) => `POST ${BASE}${s}`));

// ------------------------------------------------------------------------------------------------ router

async function callService(name, request, env) {
  let body;
  try {
    body = JSON.parse(await request.text());
  } catch {
    return invalid("request body is not valid JSON");
  }
  if (!body || typeof body !== "object" || Array.isArray(body)) return invalid("request body must be a JSON object");
  const data = body.data && typeof body.data === "object" && !Array.isArray(body.data) ? body.data : {};
  return SERVICES[name](data, env);
}

function routeError(status, code, message, extraHeaders) {
  const body = errorBody(code, `${message}. Available: ${ROUTES.join(", ")}`, "ERROR", code, "freya-statement-mock");
  return send(JSON.stringify(body), status, extraHeaders);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;
    const method = request.method.toUpperCase();

    if (method === "OPTIONS") return new Response(null, { status: 204, headers: CORS });

    if (path === "/health") {
      if (method === "GET" || method === "HEAD") return send(JSON.stringify({ ok: true }), 200);
      return routeError(405, "METHOD_NOT_ALLOWED", `${method} ${path} is not allowed, use GET`, { Allow: "GET" });
    }

    if (path === "/oauth2/token") {
      if (method !== "POST") {
        return routeError(405, "METHOD_NOT_ALLOWED", `${method} ${path} is not allowed, use POST`, { Allow: "POST" });
      }
      return send(JSON.stringify({ access_token: "test-environment-token", token_type: "Bearer", expires_in: 1800 }), 200);
    }

    if (path.startsWith(BASE) && Object.prototype.hasOwnProperty.call(SERVICES, path.slice(BASE.length))) {
      if (method !== "POST") {
        return routeError(405, "METHOD_NOT_ALLOWED", `${method} ${path} is not allowed, use POST`, { Allow: "POST" });
      }
      return callService(path.slice(BASE.length), request, env);
    }

    return routeError(404, "NOT_FOUND", `No service at ${method} ${path}`);
  },
};
